import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'
import type { Category, Compaction, Row, Selection, Turn, View } from '../types'
import { CATEGORIES, parseArgs, withNewCategories, wordsOf } from './args'
import { attachHookContext, buildReport, counterSegments, denialCategory, firstWords, NAME_COLUMN, PANE_MARGIN, paletteFor, paneHeaderCells, paneHeaderWidths, paneRowCells, paneTotalRoom, paneTotalSegments, turnTotalLines, targetOf, tokensOf, tokenValues, usageText } from './report'
import { commandsFor, enabledInstalls, pluginsFor } from './hookmatch'
import type { PluginHooks } from './hookmatch'
import { applyView, canNav, canPage, EXAMPLES, navLabel, navTarget, parseFilter, pageRows, PLACEHOLDER, rowWindow, scrollRows, scrollStep, sortMark, turnTitle, viewedTurn, withKinds, withSort } from './view'
import type { Column, Nav, Page } from './view'

// The engine follows `$` and the state atoms only within this file, never across
// an import, so every helper that takes `$` and every atom is declared here.

const ROW_CAP = 2000
const TURN_CAP = 200

const ROWS = atom({ plugin: 'xtrace', key: 'rows' } as const, [] as Row[])
const TURNS = atom({ plugin: 'xtrace', key: 'turns' } as const, [] as Turn[])
const COMPACTIONS = atom({ plugin: 'xtrace', key: 'compactions' } as const, [] as Compaction[])
const SELECTION = atom(
  { plugin: 'xtrace', key: 'selection' } as const,
  { categories: [...CATEGORIES], scope: 'turn', known: [...CATEGORIES] } as Selection,
)

const VIEW = atom({ plugin: 'xtrace', key: 'view' } as const, { filter: '', help: false } as View)

let counter = 0
const mintId = (prefix: string) => `${prefix}-${Date.now().toString(36)}-${(counter++).toString(36)}`

const MCP = /^mcp__([^_]+(?:_[^_]+)*)__(.+)$/

function splitMcp(tool: string): { server: string; name: string } | undefined {
  const m = MCP.exec(tool)
  return m && m[1] !== undefined && m[2] !== undefined ? { server: m[1], name: m[2] } : undefined
}

function addRow($: EngineInterface, row: Row) {
  return update($, ROWS, list => [...list, row].slice(-ROW_CAP))
}

function finishRow($: EngineInterface, id: string, patch: Partial<Row>) {
  return update($, ROWS, list => list.map(r => (r.id === id ? { ...r, ...patch } : r)))
}

function finishRowWith($: EngineInterface, id: string, patch: (row: Row) => Partial<Row>) {
  return update($, ROWS, list => list.map(r => (r.id === id ? { ...r, ...patch(r) } : r)))
}

function addTurn($: EngineInterface, turn: Turn) {
  return update($, TURNS, list => [...list, turn].slice(-TURN_CAP))
}

// The engine's clock for display only: a report or a drawing never fails for want of it.
async function nowOrUndefined($: EngineInterface): Promise<number | undefined> {
  try { return await $.clock.now() } catch { return undefined }
}

function completeTurn($: EngineInterface, turnId: string, completedAt: number) {
  return update($, TURNS, list => list.map(t => (t.turnId === turnId ? { ...t, isComplete: true, completedAt } : t)))
}

async function currentTurnId($: EngineInterface): Promise<string> {
  const turns = await read($, TURNS)
  return turns.at(-1)?.turnId ?? 'before-first-turn'
}

// Merged settings, read in session.start (which a hot reload fires again).
let settings: unknown = undefined

// The enabled plugins' hooks.json files, read in session.start after settings.
let pluginHooks: PluginHooks[] = []

async function loadPluginHooks($: EngineInterface, cwd: string | undefined): Promise<PluginHooks[]> {
  const home = await $.env.get('HOME')
  const configDir = (await $.env.get('CLAUDE_CONFIG_DIR')) ?? (home !== undefined ? `${home}/.claude` : undefined)
  if (configDir === undefined) return []
  const installed = JSON.parse(await $.fs.read(`${configDir}/plugins/installed_plugins.json`))
  const out: PluginHooks[] = []
  for (const p of enabledInstalls(settings, installed, cwd)) {
    try { out.push({ name: p.name, config: JSON.parse(await $.fs.read(`${p.installPath}/hooks/hooks.json`)) }) } catch {}
  }
  return out
}

// One helper for every classic event; each registration names its event literally.
async function recordHook(event: string, $: EngineInterface, e: any, next: (e: any) => Promise<any>) {
  const toolName: string | undefined = typeof e.tool_name === 'string' ? e.tool_name : typeof e.tool === 'string' ? e.tool : undefined
  const id = mintId('hook')
  let startedAt = 0
  try {
    startedAt = await $.clock.now()
    await addRow($, {
      id, turnId: await currentTurnId($), kind: 'hooks',
      name: toolName ? `${event} ${toolName}` : event,
      target: commandsFor(settings, event, toolName).join(', '),
      plugins: pluginsFor(pluginHooks, event, toolName).join(', '),
      outcome: 'running', startedAt,
    })
  } catch {}
  const ran = await next(e)
  try {
    const r = (ran ?? {}) as Record<string, unknown>
    const blocked = r.deny !== undefined || r.block !== undefined || r.preventContinuation === true || r.decision === 'block'
    const context = Array.isArray(r.additionalContext) && r.additionalContext.length > 0
    const ms = (await $.clock.now()) - startedAt
    // Context appended while the hook ran has already marked the row; keep it.
    await update($, ROWS, list => list.map(row => row.id !== id ? row : {
      ...row, ms,
      outcome: blocked ? 'blocked' : context || (row.chars ?? 0) > 0 ? 'context' : 'none',
    }))
  } catch {}
  return ran
}

// The menu dialog and the live pane.

const MENU = 'xtrace-menu'
const PANE = 'xtrace'
const PANE_PREF = 'pane'
const NARROW = 'xtrace: widen the terminal to 144 columns to see the pane'

function toggleCategory(s: Selection, c: Category): Selection {
  return {
    ...s,
    categories: s.categories.includes(c)
      ? s.categories.filter(x => x !== c)
      : CATEGORIES.filter(x => x === c || s.categories.includes(x)),
  }
}

async function isPanePreferred($: EngineInterface): Promise<boolean> {
  try { return (await $.store.get(PANE_PREF)) === true } catch { return false }
}

async function openPane($: EngineInterface): Promise<void> {
  const opened = await $.ui.open({ id: PANE, title: 'xtrace' })
  if (!opened.isPlaced) $.ui.toast(NARROW)
}

async function setPane($: EngineInterface, mode: 'on' | 'off' | 'toggle'): Promise<'on' | 'off'> {
  const want = mode === 'toggle' ? !(await isPanePreferred($)) : mode === 'on'
  await $.store.set(PANE_PREF, want)
  if (want) await openPane($)
  else await $.ui.close({ id: PANE })
  return want ? 'on' : 'off'
}

async function setFilter($: EngineInterface, filter: string): Promise<void> {
  try { await update($, VIEW, v => ({ ...v, filter, rowStart: undefined })) } catch {}
}

async function sortBy($: EngineInterface, column: Column): Promise<void> {
  try { await update($, VIEW, v => ({ ...v, filter: withSort(v.filter, column), rowStart: undefined })) } catch {}
}

// Read the turns at press time, so a press at an end (or a fast double press) is a no-op.
async function navigate($: EngineInterface, to: Nav): Promise<void> {
  try {
    const turns = await read($, TURNS)
    const { pinnedTurnId } = await read($, VIEW)
    if (!canNav(turns, pinnedTurnId, to)) return
    await update($, VIEW, v => ({ ...v, pinnedTurnId: navTarget(turns, v.pinnedTurnId, to), rowStart: undefined }))
  } catch {}
}

// The row window as last drawn: a scroll or a page press moves it by what was on screen.
// One pane, so the last drawing is the one on screen.
let drawnWindow = { count: 0, room: 1, sorted: false, turnId: undefined as string | undefined }

// A row start belongs to the turn it was set on: another turn starts from its default.
const startFor = (v: View, turnId: string | undefined) => (v.rowTurnId === turnId ? v.rowStart : undefined)

async function moveRows($: EngineInterface, by: number | Page): Promise<void> {
  const { count, room, sorted, turnId } = drawnWindow
  try {
    await update($, VIEW, v => {
      const start = startFor(v, turnId)
      return { ...v, rowTurnId: turnId, rowStart: typeof by === 'number' ? scrollRows(count, room, start, sorted, by) : pageRows(count, room, start, sorted, by) }
    })
  } catch {}
}

// A one-pixel line as wide as its box; dashed for the subagents' rule.
const ruleSvg = (color: string, isDashed: boolean) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="1" preserveAspectRatio="none">` +
  `<line x1="0" y1="0.5" x2="100%" y2="0.5" stroke="${color}" stroke-width="1"${isDashed ? ' stroke-dasharray="4 3"' : ''}/></svg>`

const PAGE: { dir: Page; hotkey: string; label: string }[] = [
  { dir: 'up', hotkey: 'u', label: '▲' },
  { dir: 'down', hotkey: 'd', label: '▼' },
]

const NAV: { to: Nav; hotkey: string; label: string }[] = [
  { to: 'first', hotkey: 'f', label: '⏮' },
  { to: 'prev', hotkey: 'p', label: '◀' },
  { to: 'next', hotkey: 'n', label: '▶' },
  { to: 'latest', hotkey: 'l', label: '⏭' },
]

export const register: Register = on => {
  const runningAgents: string[] = []                      // tool_use_ids of Agent calls in flight, newest last
  const parentOfAgent = new Map<string, string>()         // agentId -> Agent tool_use_id
  const deniedCalls = new Set<string>()                   // tool_use_ids auto mode denied: their error result reads as denied

  on('session.start', async ($, e, next) => {
    try { settings = await $.settings.read() } catch { settings = undefined }
    try { await update($, SELECTION, withNewCategories) } catch {}
    try { pluginHooks = await loadPluginHooks($, e.cwd) } catch { pluginHooks = [] }
    try {
      await $.command.register({
        name: 'xtrace',
        description: 'Trace every tool, MCP, skill, hook, subagent, command and context access',
        argumentHint: '[all | tools mcp skills hooks agents commands context model] [session | pane] | pane [on|off]',
      })
    } catch {}
    try {
      if (await isPanePreferred($)) await openPane($)
    } catch {}
    return next(e)
  })

  // /clear ends the session but keeps the process and this plugin's state:
  // empty the record so the pane and the report start from nothing. The
  // filter bar, the help flag, the menu's ticks and the pane preference stay.
  on('session.end', async ($, e, next) => {
    if (e.reason === 'clear') {
      runningAgents.length = 0
      parentOfAgent.clear()
      deniedCalls.clear()
      try { await update($, ROWS, () => []) } catch {}
      try { await update($, TURNS, () => []) } catch {}
      try { await update($, COMPACTIONS, () => []) } catch {}
      try { await update($, VIEW, v => ({ ...v, pinnedTurnId: undefined, rowStart: undefined, rowTurnId: undefined })) } catch {}
      try { if (await isPanePreferred($)) await openPane($) } catch {}
    }
    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    try {
      await addTurn($, { turnId: e.turnId, text: firstWords(e.text), startedAt: await $.clock.now(), isComplete: false })
    } catch {}
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    try {
      if (e.agentId === undefined) await completeTurn($, e.turnId, await $.clock.now())
    } catch {}
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const tool = String(e.tool)
    const { tool: _t, tool_use_id, agentId, consent: _c, ...args } = e as Record<string, unknown> & { tool_use_id?: string; agentId?: string }
    const id = typeof tool_use_id === 'string' ? tool_use_id : mintId('call')
    const mcp = splitMcp(tool)
    let startedAt = 0
    try {
      startedAt = await $.clock.now()
      const agent = typeof agentId === 'string' ? agentId : undefined
      let parentId: string | undefined
      if (agent !== undefined) {
        parentId = parentOfAgent.get(agent)
        if (parentId === undefined) {
          parentId = runningAgents.at(-1)
          if (parentId !== undefined) parentOfAgent.set(agent, parentId)
        }
      }
      const row: Row = {
        id,
        turnId: await currentTurnId($),
        agentId: agent,
        parentId,
        kind: mcp ? 'mcp' : tool === 'Agent' ? 'agents' : 'tools',
        name: mcp ? `${mcp.server} / ${mcp.name}` : tool === 'Agent' ? String(args.subagent_type ?? 'general-purpose') : tool,
        target: tool === 'Agent' ? String(args.description ?? '') : targetOf(tool, args),
        outcome: 'running',
        startedAt,
      }
      await addRow($, row)
      if (tool === 'Agent') runningAgents.push(id)
    } catch {}

    try {
      const ran = await next(e)
      try {
        const ms = (await $.clock.now()) - startedAt
        const outcome: Row['outcome'] = ran.deny !== undefined || deniedCalls.has(id) ? 'denied' : ran.isError === true ? 'error' : 'ok'
        // What the model reads back: the result text, the deny text, and any reminders riding along.
        const read = typeof ran.text === 'string' ? ran.text : typeof ran.deny === 'string' ? ran.deny : ''
        const chars = read.length + (ran.context ?? []).reduce((n: number, c: string) => n + c.length, 0)
        await finishRow($, id, { outcome, ms, chars })
      } catch {}
      return ran
    } finally {
      const at = runningAgents.indexOf(id)
      if (at >= 0) runningAgents.splice(at, 1)
    }
  })

  on('agent.spawn', async ($, e, next) => {
    const ran = await next(e)
    try {
      await finishRow($, e.tool_use_id, { detail: ran.model ?? e.model ?? 'inherit' })
      if (ran.agentId !== undefined) parentOfAgent.set(ran.agentId, e.tool_use_id)
    } catch {}
    return ran
  })

  // One row per model request, with the usage the API reported for it.
  on('turn.step', async function* ($, e, next) {
    const id = mintId('step')
    let startedAt = 0
    try {
      startedAt = await $.clock.now()
      const agent = typeof e.agentId === 'string' ? e.agentId : undefined
      await addRow($, {
        id, turnId: await currentTurnId($), agentId: agent,
        parentId: agent !== undefined ? parentOfAgent.get(agent) ?? runningAgents.at(-1) : undefined,
        kind: 'model', name: `step ${e.index}`, target: e.model, outcome: 'running', startedAt,
      })
    } catch {}
    const r = yield* next(e)
    try {
      const u = r.usage
      const usage = u ? { model: u.model, input: u.input_tokens, cacheRead: u.cache_read_input_tokens, cacheWrite: u.cache_creation_input_tokens, output: u.output_tokens } : undefined
      await finishRow($, id, {
        outcome: usage ? 'ok' : 'error', ms: (await $.clock.now()) - startedAt,
        usage, target: usage ? usageText(usage) : e.model,
      })
    } catch {}
    return r
  })

  on('skill.prompt', async ($, e, next) => {
    const ran = await next(e)
    try {
      await addRow($, {
        id: mintId('skill'), turnId: await currentTurnId($), kind: 'skills',
        name: e.skill, target: `${ran.text.length} chars`, chars: ran.text.length, outcome: 'ok', startedAt: await $.clock.now(),
      })
    } catch {}
    return ran
  })

  on('command.run', { command: 'xtrace' }, async ($, e) => {
    const parsed = parseArgs(e.args)
    if (parsed.mode === 'error') return { text: parsed.message }
    if (parsed.mode === 'menu') {
      const opened = await $.ui.open({ id: MENU, title: 'xtrace', focus: true, closeOnEscape: true, rows: 14 })
      return { text: opened.isPlaced ? 'xtrace: pick what to show.' : `xtrace: ${opened.reason}` }
    }
    if (parsed.mode === 'pane') {
      if (parsed.kinds === undefined) return { text: `xtrace: live pane ${await setPane($, parsed.pane)}.` }
      const filter = withKinds((await read($, VIEW)).filter, parsed.kinds)
      await setFilter($, filter)
      await setPane($, 'on')
      return { text: `xtrace: live pane on, filter "${filter}".` }
    }
    // The save is for the menu's ticks; a refused write (the engine refuses
    // one while a ui.render hook draws, e.g. with the menu open) must not
    // cost the report.
    try { await update($, SELECTION, () => ({ ...parsed.selection, known: [...CATEGORIES] })) } catch {}
    const [rows, turns, compactions] = await Promise.all([read($, ROWS), read($, TURNS), read($, COMPACTIONS)])
    return { text: buildReport({ rows, turns, compactions, selection: parsed.selection, now: await nowOrUndefined($) }) }
  })

  on('command.run', async ($, e, next) => {
    if (e.command === 'xtrace') return next(e)
    const id = mintId('cmd')
    let startedAt = 0
    try {
      startedAt = await $.clock.now()
      await addRow($, { id, turnId: await currentTurnId($), kind: 'commands', name: e.command, target: e.args, outcome: 'running', startedAt })
    } catch {}
    try {
      const ran = await next(e)
      try { await finishRow($, id, { outcome: 'ok', ms: (await $.clock.now()) - startedAt }) } catch {}
      return ran
    } catch (err) {
      try { await finishRow($, id, { outcome: 'error', ms: (await $.clock.now()) - startedAt }) } catch {}
      throw err
    }
  })

  on('session.append', async ($, e, next) => {
    try {
      if (e.door === 'attachment' || e.door === 'hook-context') {
        const text = e.message.content.map(b => (b.type === 'text' ? b.text : '')).join('')
        if (text.length === 0) return next(e)                // an empty append says nothing
        const turnId = await currentTurnId($)
        if (e.origin.kind === 'hook') {
          // A hook's context belongs on its hooks row; a row of its own only when there is none.
          const event = e.origin.event
          let merged = false
          await update($, ROWS, list => {
            const attached = attachHookContext(list, turnId, event, text.length)
            merged = attached !== undefined
            return attached ?? list
          })
          if (merged) return next(e)
        }
        const name = e.origin.kind === 'hook' ? `hook ${e.origin.event}` : `${e.door} ${e.message.name ?? ''}`.trim()
        await addRow($, {
          id: e.uuid, turnId, agentId: e.agentId, kind: 'context',
          name, target: `${text.length} chars`, chars: text.length, outcome: 'ok', startedAt: await $.clock.now(),
        })
      }
    } catch {}
    return next(e)
  })

  on('session.compact', async ($, e, next) => {
    const ran = await next(e)
    try {
      // Only a main-conversation compaction that happened (not a skip or a precompute).
      if (e.agentId === undefined && ran.skip === undefined && e.trigger !== 'precompute') {
        const turnId = await currentTurnId($)
        const at = await $.clock.now()
        await update($, COMPACTIONS, list => [...list, { at, turnId }].slice(-50))
      }
    } catch {}
    return ran
  })

  on('classic.PreToolUse', ($, e, next) => recordHook('PreToolUse', $, e, next))
  on('classic.PostToolUse', ($, e, next) => recordHook('PostToolUse', $, e, next))
  on('classic.PostToolUseFailure', ($, e, next) => recordHook('PostToolUseFailure', $, e, next))
  on('classic.UserPromptSubmit', ($, e, next) => recordHook('UserPromptSubmit', $, e, next))
  on('classic.Stop', ($, e, next) => recordHook('Stop', $, e, next))
  on('classic.SessionStart', ($, e, next) => recordHook('SessionStart', $, e, next))
  on('classic.SessionEnd', ($, e, next) => recordHook('SessionEnd', $, e, next))
  on('classic.SubagentStart', ($, e, next) => recordHook('SubagentStart', $, e, next))
  on('classic.SubagentStop', ($, e, next) => recordHook('SubagentStop', $, e, next))
  on('classic.PreCompact', ($, e, next) => recordHook('PreCompact', $, e, next))
  on('classic.PostCompact', ($, e, next) => recordHook('PostCompact', $, e, next))
  on('classic.Notification', ($, e, next) => recordHook('Notification', $, e, next))
  on('classic.PermissionRequest', ($, e, next) => recordHook('PermissionRequest', $, e, next))
  // Auto mode answers a call it denies as an ordinary error result; this event says
  // which call it was and why. Before or after the call finished, its row reads denied.
  on('classic.PermissionDenied', async ($, e, next) => {
    try {
      const id = typeof e.tool_use_id === 'string' ? e.tool_use_id : undefined
      if (id !== undefined && !deniedCalls.has(id)) {
        deniedCalls.add(id)
        const why = typeof e.reason === 'string' ? denialCategory(e.reason) : undefined
        await finishRowWith($, id, row => ({ outcome: row.outcome === 'running' ? row.outcome : 'denied', target: why !== undefined ? `[${why}] ${row.target}` : row.target }))
      }
    } catch {}
    return recordHook('PermissionDenied', $, e, next)
  })
  // The pane is drawn to fit, so the engine never scrolls it: a wheel tick or a
  // scroll key moves the row window instead, and the window stays undrawn.
  // Rows that fit leave the scroll to the engine, so a pane too short for its fixed lines still scrolls.
  on('ui.scroll', { requestId: PANE }, async ($, e, next) => {
    if (drawnWindow.count <= drawnWindow.room) return next(e)
    await moveRows($, scrollStep(e.by, e.bodyRows))
    return {}
  })

  on('ui.close', async ($, e, next) => {
    try {
      // The person closed the pane with the engine's own key: remember it as off.
      if (e.id === PANE && e.origin.kind === 'person') await $.store.set(PANE_PREF, false)
    } catch {}
    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: MENU }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const s = await read($, SELECTION)
    const isAll = CATEGORIES.every(c => s.categories.includes(c))
    const canShow = s.categories.length > 0

    return (
      <Box flexDirection="column">
        <Text bold>What should /xtrace show?</Text>
        {CATEGORIES.map((c, i) => (
          <Button
            key={`cat-${c}`}
            hotkey={String(i + 1)}
            plain
            label={`[${s.categories.includes(c) ? 'x' : ' '}] ${c}`}
            onPress={() => update($, SELECTION, cur => toggleCategory(cur, c))}
          />
        ))}
        <Text> </Text>
        <Button key="all" hotkey="a" plain label={`[${isAll ? 'x' : ' '}] all`}
          onPress={() => update($, SELECTION, cur => ({ ...cur, categories: isAll ? [] : [...CATEGORIES] }))} />
        <Button key="scope" hotkey="s" plain label={`[${s.scope === 'session' ? 'x' : ' '}] whole session`}
          onPress={() => update($, SELECTION, cur => ({ ...cur, scope: cur.scope === 'session' ? 'turn' : 'session' }))} />
        <Button key="pane" hotkey="p" plain label="toggle live pane"
          onPress={async () => { await setPane($, 'toggle') }} />
        <Text> </Text>
        <Box gap={2}>
          <Button key="show" hotkey="0" variant="primary" label="show" dimColor={!canShow}
            onPress={async () => {
              if (!canShow) return
              const cur = await read($, SELECTION)
              await $.ui.close({ id: MENU })
              await $.command.run({ command: 'xtrace', args: wordsOf(cur) })
            }} />
          <Button key="cancel" role="dismiss" label="cancel" onPress={() => $.ui.close({ id: MENU })} />
        </Box>
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const elements = $.ui.resolve(e)
    const { Box, Text, Button, Input } = elements
    // Off the terminal (whose table draws an Svg as nothing), rules are lines, not text.
    const Svg = e.surface !== 'terminal' && 'Svg' in elements ? elements.Svg : undefined
    const rows: Row[] = await read($, ROWS)
    const turns: Turn[] = await read($, TURNS)
    const view: View = await read($, VIEW)
    const pal = paletteFor((await $.config.list().catch(() => [])).find(row => row.key === 'theme')?.value)
    const counters = counterSegments(CATEGORIES.map(c => [c, rows.filter(r => r.kind === c).length]), pal)
    const { turn } = viewedTurn(turns, view.pinnedTurnId)
    const turnId = turn?.turnId
    const turnRows = rows.filter(r => r.turnId === turnId)
    // An old turn with no rows left: the 2000-row buffer dropped them.
    const isEvicted = turn !== undefined && turn.turnId !== turns.at(-1)?.turnId && turnRows.length === 0 && rows.length >= ROW_CAP
    const tokens = tokensOf(turnRows)
    const counts = new Map([...tokenValues(turnRows)].map(([id, v]) => [id, v.n]))
    const parsed = parseFilter(view.filter)
    const shown = applyView(turnRows, parsed, counts)
    const isFiltered = view.filter.trim() !== ''
    const now = await nowOrUndefined($)
    const total = turn !== undefined && now !== undefined ? turnTotalLines(turn, rows, now) : undefined
    const extra = (view.help ? EXAMPLES.length : 0) + (parsed.errors.length > 0 ? 1 : 0) + (isFiltered ? 1 : 0)
    const agentsAt = total?.findIndex(line => line.startsWith('subagents:')) ?? -1
    // The pane's own rows, not the terminal's: content taller than the pane scrolls,
    // and a scrolled pane draws the filter's cursor on the wrong row.
    const bodyRows = e.props.scroll.bodyRows > 0 ? e.props.scroll.bodyRows : (e.viewport?.rows ?? 24)
    // Counters, filter bar, rule, [prompt, rule,] header, the rows, rule, the total's lines, rule, nav.
    const base = Math.max(1, bodyRows - 7 - (turn !== undefined ? 2 : 0) - extra - (total?.length ?? 0) - (agentsAt > 0 ? 1 : 0))
    const width = e.props.bodyColumns > 0 ? e.props.bodyColumns : 80
    const ruleWidth = Math.max(1, Math.min(width, 120))
    // A rule one line high across its width. The terminal draws it as text; a surface
    // with proportional text (the desktop) would wrap `─` onto a second line, which
    // its boxes do not clip, so there it is an SVG line filling the box.
    const rule = (key: string, w = ruleWidth, char = '─') => (
      <Box key={key} width={w} height={1} overflow="hidden" alignItems="center">
        {Svg !== undefined
          ? <Svg alt="" source={ruleSvg(pal.separator, char !== '─')} />
          : <Text dimColor wrap="truncate-end">{char.repeat(w)}</Text>}
      </Box>
    )
    const withPlugins = shown.some(r => r.kind === 'hooks')
    const marks = parsed.sort !== undefined ? { [parsed.sort.column]: sortMark(parsed.sort, parsed.sort.column) } : {}
    const header = paneHeaderCells(width, withPlugins, marks)
    const columnWidths = paneHeaderWidths(width, withPlugins)
    // Unsorted, the newest rows that fit; sorted, the first ones in order.
    // A turn that overflows gives one line to the paging line: the earlier-rows hint and its controls.
    const overflows = shown.length > base
    const room = overflows ? Math.max(1, base - 1) : base
    const sorted = parsed.sort !== undefined
    const rowStart = startFor(view, turnId)
    const win = rowWindow(shown.length, room, rowStart, sorted)
    const visible = shown.slice(win.from, win.to)
    drawnWindow = { count: shown.length, room, sorted, turnId }
    // The paging line spans the rows (they end PANE_MARGIN short of the pane's edge);
    // its controls, `u: ▲ d: ▼`, take 9 columns in the middle.
    const pagingWidth = Math.max(9, width - PANE_MARGIN)
    const pagingSide = Math.floor((pagingWidth - 9) / 2)

    return (
      // At least the pane's height, so the spacer below can push the footer to the bottom;
      // an overfull tree still grows and scrolls.
      <Box flexDirection="column" minHeight={bodyRows}>
        <Text wrap="truncate-end">
          {counters.map((s, i) => <Text key={`count-${i}`} color={s.color}>{s.text}</Text>)}
        </Text>
        <Box flexDirection="row" gap={2}>
          {/* Our own label: the engine draws an Input's label as dim as its placeholder. */}
          <Box flexDirection="row" gap={1}>
            <Box key="filter-label"><Text color={pal.value}>filter:</Text></Box>
            <Input key="filter" autoFocus placeholder={PLACEHOLDER} value={view.filter} submitLabel="keep"
              onInput={value => setFilter($, value)} onSubmit={value => setFilter($, value)} />
          </Box>
          <Button key="help" hotkey="h" plain label="?"
            onPress={async () => { try { await update($, VIEW, v => ({ ...v, help: !v.help })) } catch {} }} />
        </Box>
        {parsed.errors.length > 0 && <Box key="filter-error"><Text dimColor wrap="truncate-end">{parsed.errors.join(' · ')}</Text></Box>}
        {view.help && EXAMPLES.map(x => (
          <Text key={`example-${x.text}`} dimColor wrap="truncate-end">{`  ${x.text.padEnd(28)} ${x.meaning}`}</Text>
        ))}
        {rule('rule-top')}
        {turn !== undefined && (
          <Box key="prompt">
            <Text wrap="truncate-end">
              <Text color={pal.label}>prompt: </Text>
              <Text color={pal.value}>{turnTitle(turn.text)}</Text>
            </Text>
          </Box>
        )}
        {turn !== undefined && rule('rule-prompt')}
        {isEvicted && <Box key="evicted"><Text dimColor>rows for this turn fell out of the 2000-row buffer</Text></Box>}
        {!isEvicted && turnRows.length === 0 && <Text dimColor>No rows in this turn yet.</Text>}
        {turnRows.length > 0 && (
          // Each label in a box of its column's width, like the rows' cells, so they line up
          // on a surface that draws proportional text too.
          <Box flexDirection="row" gap={1}>
            {header.map((c, i) => {
              const label = c.text.trim()
              const isLast = i === header.length - 1
              const sort = <Button key={`sort-${c.column}`} plain dimColor label={label} onPress={() => sortBy($, c.column as Column)} />
              return (
                <Box key={`hcell-${c.column}`} width={columnWidths[i] ?? 1} flexShrink={0}
                  justifyContent={isLast ? 'flex-end' : 'flex-start'}>
                  {e.surface === 'terminal' ? sort : [
                    // The desktop draws a native button, padded: at rest the label is text, lined
                    // up with the cells below; under the pointer the button shows over it.
                    <Text key={`hlabel-${c.column}`} dimColor wrap="truncate-end">{label}</Text>,
                    // Unkeyed: the keyed cell is the hover scope, a keyed Box would be its own.
                    <Box position="absolute" top={0} {...(isLast ? { right: 0 } : { left: 0 })}
                      display="none" hover={{ display: 'flex' }}>
                      {sort}
                    </Box>,
                  ]}
                </Box>
              )
            })}
          </Box>
        )}
        {overflows && (
          // Three parts: the hint at the left, the controls in the middle, the range and ↓ at
          // the right edge of the rows (the ms column's end). Equal sides keep the middle centred.
          <Box key="paging" flexDirection="row" width={pagingWidth}>
            <Box width={pagingSide} justifyContent="flex-start">
              {win.from > 0 && <Box key="hidden"><Text dimColor wrap="truncate-end">{`↑ ${win.from} ${sorted ? 'rows above' : 'earlier rows'}`}</Text></Box>}
            </Box>
            <Box width={pagingWidth - 2 * pagingSide} justifyContent="center" gap={1}>
              {PAGE.map(b => (
                <Button key={`page-${b.dir}`} hotkey={b.hotkey} plain label={b.label}
                  dimColor={!canPage(shown.length, room, rowStart, sorted, b.dir)} onPress={() => moveRows($, b.dir)} />
              ))}
            </Box>
            <Box width={pagingSide} justifyContent="flex-end" gap={1}>
              <Box key="page-label"><Text dimColor wrap="truncate-end">{`rows ${win.from + 1}–${win.to} of ${shown.length}`}</Text></Box>
              <Text dimColor>↓</Text>
            </Box>
          </Box>
        )}
        {visible.map(r => (
          <Box key={`row-${r.id}`} flexDirection="row" gap={1}>
            {paneRowCells(r, width, withPlugins, tokens.get(r.id), pal).map((c, i) => (
              <Box key={`${r.id}-${i}`} width={c.width} flexShrink={0} justifyContent={c.isRight ? 'flex-end' : 'flex-start'}>
                <Text color={c.color} bold={c.bold} wrap="truncate-end">{c.text}</Text>
              </Box>
            ))}
          </Box>
        ))}
        {/* The free space: the totals and the nav row stay at the bottom of the pane. */}
        <Box key="footer-spacer" flexGrow={1} />
        {turnRows.length > 0 && total !== undefined && rule('rule-total')}
        {turnRows.length > 0 && total !== undefined && (
          <Box flexDirection="column">
            {total.flatMap((line, n) => [
              // A short rule sets the subagents' block apart from the main loop's.
              ...(n === agentsAt && n > 0 ? [rule('agents-rule', Math.min(24, ruleWidth), '╌')] : []),
              // The lead (`Total:` or the indent) in a box of the kind column's width, so the
              // figures start under the name column on any surface.
              (() => {
                const [lead, ...rest] = paneTotalSegments(line, width, n === 0, pal, e.surface === 'terminal')
                return (
                  <Box key={`total-${n}`} flexDirection="row">
                    <Box key={`total-${n}-lead`} width={NAME_COLUMN} flexShrink={0}>
                      <Text color={lead?.color} bold={lead?.bold}>{lead?.text.trim() ?? ''}</Text>
                    </Box>
                    {/* The figures take the room up to the margin and are cut at its edge. */}
                    <Box key={`total-${n}-figures`} width={paneTotalRoom(width)} flexShrink={1}>
                      <Text wrap="truncate-end">
                        {rest.map((s, i) => <Text key={`total-${n}-${i}`} color={s.color} bold={s.bold}>{s.text}</Text>)}
                      </Text>
                    </Box>
                  </Box>
                )
              })(),
            ])}
          </Box>
        )}
        {turnRows.length > 0 && isFiltered && <Box key="shown"><Text dimColor>{`${shown.length} of ${turnRows.length} rows shown`}</Text></Box>}
        {turnRows.length > 0 && total !== undefined && rule('rule-nav')}
        <Box key="nav" flexDirection="row" gap={1} width={ruleWidth} justifyContent="center">
          {NAV.map(b => {
            const can = canNav(turns, view.pinnedTurnId, b.to)
            return <Button key={`nav-${b.to}`} hotkey={b.hotkey} plain label={b.label} dimColor={!can}
              onPress={() => navigate($, b.to)} />
          })}
          <Box key="nav-label"><Text dimColor wrap="truncate-end">{navLabel(turns, view.pinnedTurnId)}</Text></Box>
        </Box>
      </Box>
    )
  })
}

files.hooks/args.ts:
import type { Category, Selection } from '../types'

export const CATEGORIES: readonly Category[] = [
  'tools', 'mcp', 'skills', 'hooks', 'agents', 'commands', 'context', 'model',
]

export const USAGE =
  'Usage: /xtrace [all | tools mcp skills hooks agents commands context model] [session] | /xtrace [categories] pane | /xtrace pane [on|off]'

export type ParsedArgs =
  | { mode: 'menu' }
  | { mode: 'report'; selection: Selection }
  | { mode: 'pane'; pane: 'on' | 'off' | 'toggle'; kinds?: Category[] | 'all' }
  | { mode: 'error'; message: string; selection?: undefined }

const isCategory = (word: string): word is Category =>
  (CATEGORIES as readonly string[]).includes(word)

const error = (message: string): ParsedArgs => ({ mode: 'error', message: `${message} ${USAGE}` })

// `pane` anywhere: on, off or a toggle; categories with it open the pane filtered to them.
function parsePane(words: string[]): ParsedArgs {
  if (words.filter(w => w === 'pane').length > 1) return error('Name "pane" once.')
  let pane: 'on' | 'off' | undefined
  let all = false
  const picked = new Set<Category>()
  for (const word of words) {
    if (word === 'pane') continue
    if (word === 'on' || word === 'off') {
      if (pane !== undefined) return error(`Unknown pane option "${word}".`)
      pane = word
    } else if (word === 'all') all = true
    else if (word === 'session') return error('The pane shows one turn; "session" is for the report.')
    else if (isCategory(word)) picked.add(word)
    else return error(`Unknown word "${word}".`)
  }
  if (!all && picked.size === 0) return { mode: 'pane', pane: pane ?? 'toggle' }
  if (pane === 'off') return error('"pane off" takes no categories.')
  return { mode: 'pane', pane: 'on', kinds: all ? 'all' : CATEGORIES.filter(c => picked.has(c)) }
}

export function parseArgs(text: string): ParsedArgs {
  const words = text.trim().toLowerCase().split(/\s+/).filter(Boolean)
  if (words.length === 0) return { mode: 'menu' }
  if (words.includes('pane')) return parsePane(words)

  const picked = new Set<Category>()
  let scope: Selection['scope'] = 'turn'
  for (const word of words) {
    if (word === 'all') CATEGORIES.forEach(c => picked.add(c))
    else if (word === 'session') scope = 'session'
    else if (isCategory(word)) picked.add(word)
    else return error(`Unknown word "${word}".`)
  }
  if (picked.size === 0) return error('Name at least one category.')
  return {
    mode: 'report',
    selection: { categories: CATEGORIES.filter(c => picked.has(c)), scope },
  }
}

export function wordsOf(selection: Selection): string {
  const isAll = CATEGORIES.every(c => selection.categories.includes(c))
  const words = isAll ? ['all'] : CATEGORIES.filter(c => selection.categories.includes(c))
  if (selection.scope === 'session') words.push('session')
  return words.join(' ')
}

// The categories before `known` was stored: a selection without it knew these.
const FIRST_CATEGORIES: readonly Category[] = ['tools', 'mcp', 'skills', 'hooks', 'agents', 'commands', 'context']

// A category added after the selection was saved starts switched on; one the
// person switched off stays off.
export function withNewCategories(s: Selection): Selection {
  const known = s.known ?? FIRST_CATEGORIES
  const added = CATEGORIES.filter(c => !known.includes(c))
  return { ...s, categories: CATEGORIES.filter(c => s.categories.includes(c) || added.includes(c)), known: [...CATEGORIES] }
}

files.hooks/report.ts:
import type { Category, Compaction, Row, Selection, Turn, Usage } from '../types'

const TARGET_MAX = 80
const FILE_TOOLS = new Set(['Read', 'Edit', 'Write', 'NotebookEdit'])
const EDIT_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])
const CHECK_RUNNERS = ['go test', 'npm test', 'pnpm test', 'yarn test', 'pytest', 'gradle', './gradlew', 'mvn', 'cargo test', 'make']

const str = (v: unknown): string | undefined => (typeof v === 'string' ? v : undefined)

export function trim(text: string, max = TARGET_MAX): string {
  const one = text.replace(/\s+/g, ' ').trim()
  return one.length <= max ? one : one.slice(0, max - 1) + '…'
}

// What auto mode's denial reason names: its leading `[Category]`, else the reason itself, shortened.
export function denialCategory(reason: string): string | undefined {
  const text = reason.trim()
  if (text === '') return undefined
  return /^\[([^\]]+)\]/.exec(text)?.[1] ?? firstWords(text, 7)
}

export function firstWords(text: string, n = 8): string {
  const words = text.trim().split(/\s+/).filter(Boolean)
  return words.length <= n ? words.join(' ') : words.slice(0, n).join(' ') + '…'
}

export function targetOf(tool: string, args: Record<string, unknown>): string {
  const path = str(args.file_path)
  if (FILE_TOOLS.has(tool) && path !== undefined) {
    const offset = typeof args.offset === 'number' ? args.offset : undefined
    const limit = typeof args.limit === 'number' ? args.limit : undefined
    if (offset !== undefined && limit !== undefined) return trim(`${path} ${offset}–${offset + limit - 1}`)
    return trim(path)
  }
  if (tool === 'Grep' || tool === 'Glob') {
    const pattern = str(args.pattern) ?? ''
    const where = str(args.path)
    return trim(where ? `\`${pattern}\` in ${where}` : `\`${pattern}\``)
  }
  if (tool === 'Bash') return trim(str(args.command) ?? '')
  if (tool === 'Agent') return trim(`${str(args.subagent_type) ?? 'general-purpose'}: ${str(args.description) ?? ''}`)
  if (tool === 'Skill') return trim(str(args.skill) ?? '')
  for (const value of Object.values(args)) {
    const s = str(value)
    if (s !== undefined) return trim(s)
  }
  return ''
}

// --- Tokens -----------------------------------------------------------------

export function fmtTokens(n: number): string {
  return n < 1000 ? String(Math.round(n)) : `${(n / 1000).toFixed(1)}k`
}

// Everything the request was answered over: uncached, read from cache, written to it.
export const contextOf = (u: Usage): number => u.input + u.cacheRead + u.cacheWrite

export function usageText(u: Usage): string {
  return `${u.model} · in ${fmtTokens(u.input)} · cache ${fmtTokens(u.cacheRead)} · write ${fmtTokens(u.cacheWrite)} · out ${fmtTokens(u.output)}`
}

// What each row added to the context. Model rows: their request's output,
// exact. Other rows with text: about chars / 4, then corrected per loop: the
// growth between two requests (next context − this context − this output)
// is split over the rows recorded between them by their share of the text.
export type TokenValue = { n: number; exact: boolean }

export function tokenValues(rows: Row[]): Map<string, TokenValue> {
  const out = new Map<string, TokenValue>()
  const groups = new Map<string, Row[]>()
  for (const r of rows) {
    if (r.kind === 'model' && r.usage !== undefined) out.set(r.id, { n: r.usage.output, exact: true })   // what it wrote; stays in the context
    else if (r.chars !== undefined && r.chars > 0) out.set(r.id, { n: Math.ceil(r.chars / 4), exact: false })
    const key = `${r.turnId}|${r.agentId ?? ''}`
    groups.set(key, [...(groups.get(key) ?? []), r])
  }
  for (const group of groups.values()) {
    const sorted = [...group].sort((a, b) => a.startedAt - b.startedAt)
    const steps = sorted.filter(r => r.kind === 'model' && r.usage !== undefined)
    for (let i = 0; i + 1 < steps.length; i++) {
      const a = steps[i]
      const b = steps[i + 1]
      if (a?.usage === undefined || b?.usage === undefined) continue
      const grown = contextOf(b.usage) - contextOf(a.usage) - a.usage.output
      const between = sorted.filter(r => r.kind !== 'model' && r.startedAt > a.startedAt && r.startedAt < b.startedAt && (r.chars ?? 0) > 0)
      const chars = between.reduce((sum, r) => sum + (r.chars ?? 0), 0)
      if (grown <= 0 || chars === 0) continue
      for (const r of between) out.set(r.id, { n: (grown * (r.chars ?? 0)) / chars, exact: false })
    }
  }
  return out
}

// The same values as the pane and the report print them: `+310`, `~1.0k`.
export function tokensOf(rows: Row[]): Map<string, string> {
  return new Map([...tokenValues(rows)].map(([id, v]) => [id, `${v.exact ? '+' : '~'}${fmtTokens(v.n)}`]))
}

// --- Cost -------------------------------------------------------------------

// First-party API list prices, $ per million tokens (claude-api skill, cached 2026-10-06):
// input, output, cache read. A cache write is priced at the 1-hour rate, 2x input:
// the usage a mod sees does not split 5-minute from 1-hour writes, and Claude Code
// writes 1-hour entries, so the figure is an estimate (shown with ≈).
type Price = { input: number; output: number; cacheRead: number }
const PRICES: Record<string, Price> = {
  'claude-fable-5-1': { input: 10, output: 50, cacheRead: 0.25 },
  'claude-mythos-5-1': { input: 10, output: 50, cacheRead: 0.25 },
  'claude-fable-5': { input: 10, output: 50, cacheRead: 1 },
  'claude-mythos-5': { input: 10, output: 50, cacheRead: 1 },
  'claude-opus-5-5': { input: 4, output: 20, cacheRead: 0.2 },
  'claude-opus-5': { input: 5, output: 25, cacheRead: 0.5 },
  'claude-opus-4-8': { input: 5, output: 25, cacheRead: 0.5 },
  'claude-opus-4-7': { input: 5, output: 25, cacheRead: 0.5 },
  'claude-opus-4-6': { input: 5, output: 25, cacheRead: 0.5 },
  'claude-sonnet-5-5': { input: 2, output: 10, cacheRead: 0.2 },
  'claude-sonnet-5': { input: 2, output: 10, cacheRead: 0.2 },
  'claude-sonnet-4-6': { input: 3, output: 15, cacheRead: 0.3 },
  'claude-haiku-5-5': { input: 0.1, output: 0.5, cacheRead: 0.01 },
  'claude-haiku-4-5': { input: 1, output: 5, cacheRead: 0.1 },
}
// Haiku 5.5 is priced higher for prompts over 100K tokens.
const HAIKU_LONG: Price = { input: 0.5, output: 2.5, cacheRead: 0.05 }
const CACHE_WRITE = 2

// The longest known name the id contains: `claude-opus-5-5[1m]`, `us.anthropic.claude-sonnet-5-5`.
function priceOf(u: Usage): Price | undefined {
  const name = Object.keys(PRICES).filter(k => u.model.includes(k)).sort((a, b) => b.length - a.length)[0]
  if (name === undefined) return undefined
  return name === 'claude-haiku-5-5' && contextOf(u) > 100_000 ? HAIKU_LONG : PRICES[name]
}

export function costOf(u: Usage): number | undefined {
  const p = priceOf(u)
  if (p === undefined) return undefined
  return (u.input * p.input + u.cacheWrite * p.input * CACHE_WRITE + u.cacheRead * p.cacheRead + u.output * p.output) / 1e6
}

export const fmtCost = (usd: number): string => (usd < 0.01 ? '≈<$0.01' : `≈$${usd.toFixed(2)}`)

// One line per loop for the report: requests, context growth, output, cache split.
type LoopTotals = { requests: number; from: number; to: number; output: number; cacheRead: number; input: number; cacheWrite: number; cost: number; isPartial: boolean }

// The main loop's (sub false) or the subagents' (sub true) model requests, summed.
function loopTotals(rows: Row[], sub: boolean): LoopTotals | undefined {
  const loop = rows
    .filter(r => r.kind === 'model' && r.usage !== undefined && (r.agentId !== undefined) === sub)
    .sort((a, b) => a.startedAt - b.startedAt)
  const first = loop[0]?.usage
  const last = loop.at(-1)?.usage
  if (first === undefined || last === undefined) return undefined
  const sum = (f: (u: Usage) => number) => loop.reduce((n, r) => n + (r.usage ? f(r.usage) : 0), 0)
  return {
    requests: loop.length, from: contextOf(first), to: contextOf(last),
    output: sum(u => u.output), cacheRead: sum(u => u.cacheRead), input: sum(u => u.input), cacheWrite: sum(u => u.cacheWrite),
    cost: sum(u => costOf(u) ?? 0), isPartial: loop.some(r => r.usage !== undefined && costOf(r.usage) === undefined),
  }
}

// The spend follows the context: what the loop cost at list price, `+ ?` when a model has no price.
const growthText = (t: LoopTotals) =>
  `${t.requests} request(s) · context +${fmtTokens(t.to - t.from)} (${fmtTokens(t.from)} → ${fmtTokens(t.to)}) · ${spendText(t)}`
const spendText = (t: LoopTotals) =>
  t.isPartial && t.cost === 0 ? '≈$?' : `${fmtCost(t.cost)}${t.isPartial ? ' + ?' : ''}`
const splitText = (t: LoopTotals) =>
  `output ${fmtTokens(t.output)} · cache read ${fmtTokens(t.cacheRead)} · uncached ${fmtTokens(t.input)} · cache write ${fmtTokens(t.cacheWrite)}`

function loopSummary(rows: Row[], sub: boolean): string | undefined {
  const t = loopTotals(rows, sub)
  return t === undefined ? undefined : `${growthText(t)} · ${splitText(t)}`
}

// One line per loop for the report: requests, context growth, output, cache split.
export function tokenTotals(rows: Row[]): string[] {
  const lines: string[] = []
  const main = loopSummary(rows, false)
  const sub = loopSummary(rows, true)
  if (main !== undefined) lines.push(`Tokens: ${main}`)
  if (sub !== undefined) lines.push(`Subagent tokens: ${sub}`)
  return lines
}

export function fmtDuration(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`
  const s = Math.round(ms / 1000)
  return `${Math.floor(s / 60)}m ${String(s % 60).padStart(2, '0')}s`
}

// One prompt's total, in lines short enough for a half-screen pane:
//   Total: <wall time> · <requests> · context <first> → <last> (+growth)
//   output … · cache read … · uncached … · cache write …
//   subagents: …                          (when subagents ran)
// Wall time runs from the prompt to the answer, or to now while it runs.
export function turnTotalLines(turn: Turn, rows: Row[], now: number): string[] {
  const own = rows.filter(r => r.turnId === turn.turnId)
  const lastEnd = Math.max(turn.startedAt, ...own.map(r => r.startedAt + (r.ms ?? 0)))
  const end = turn.completedAt ?? (turn.isComplete ? lastEnd : now)
  const time = `${fmtDuration(end - turn.startedAt)}${turn.isComplete ? '' : ' so far'}`
  const main = loopTotals(own, false)
  const sub = loopTotals(own, true)
  const lines = [`Total: ${time} · ${main ? growthText(main) : 'no model requests recorded'}`]
  if (main) lines.push(splitText(main))
  if (sub) lines.push(`subagents: ${growthText(sub)}`, splitText(sub))
  return lines
}

// The same on one line, for the report.
export function turnTotal(turn: Turn, rows: Row[], now: number): string {
  return turnTotalLines(turn, rows, now).join(' · ')
}

// Puts a hook's appended context on the latest hooks row of that event in the
// turn (named `Event` or `Event Tool`). Undefined when there is no such row.
export function attachHookContext(rows: Row[], turnId: string, event: string, chars: number): Row[] | undefined {
  let at = -1
  rows.forEach((r, i) => {
    if (r.kind === 'hooks' && r.turnId === turnId && (r.name === event || r.name.startsWith(`${event} `))) at = i
  })
  if (at < 0) return undefined
  return rows.map((r, i) => (i === at ? { ...r, chars: (r.chars ?? 0) + chars, outcome: 'context' as const } : r))
}

export function scopedTurns(turns: Turn[], scope: Selection['scope']): Turn[] {
  if (scope === 'session') return turns
  return turns.slice(-1)
}

const cell = (text: string | number | undefined): string => String(text ?? '').replace(/\|/g, '\\|')

function orderRows(rows: Row[], withAgents: boolean): { row: Row; indent: boolean }[] {
  const byParent = new Map<string, Row[]>()
  const top: Row[] = []
  for (const r of rows) {
    if (withAgents && r.parentId !== undefined && rows.some(p => p.id === r.parentId)) {
      const list = byParent.get(r.parentId) ?? []
      list.push(r)
      byParent.set(r.parentId, list)
    } else top.push(r)
  }
  const out: { row: Row; indent: boolean }[] = []
  for (const r of top) {
    out.push({ row: r, indent: false })
    for (const child of byParent.get(r.id) ?? []) out.push({ row: child, indent: true })
  }
  return out
}

function nameOf(row: Row, rows: Row[], withAgents: boolean, indent: boolean): string {
  if (indent) return `  ${row.name}`
  if (!withAgents && row.parentId !== undefined) {
    const parent = rows.find(p => p.id === row.parentId)
    if (parent) return `${row.name} (${parent.name})`
  }
  return row.name
}

export type ReportInput = { rows: Row[]; turns: Turn[]; compactions: Compaction[]; selection: Selection; now?: number }

export function buildReport({ rows, turns, compactions, selection, now = Date.now() }: ReportInput): string {
  const scope = scopedTurns(turns, selection.scope)
  const turnIds = new Set(scope.map(t => t.turnId))
  const picked = new Set<Category>(selection.categories)
  const all = rows.filter(r => turnIds.has(r.turnId))
  const shown = all.filter(r => picked.has(r.kind)).sort((a, b) => a.startedAt - b.startedAt)

  if (shown.length === 0) {
    return selection.scope === 'turn'
      ? 'xtrace: nothing recorded for the last turn.'
      : 'xtrace: nothing recorded for this session.'
  }

  const lines: string[] = []
  lines.push(`xtrace: ${scope.length} turn(s), ${shown.length} rows, categories: ${selection.categories.join(', ')}`)
  const compacted = compactions.filter(c => turnIds.has(c.turnId)).at(-1)
  if (compacted !== undefined) {
    const at = new Date(compacted.at).toISOString().slice(11, 19)
    lines.push(`Memory starts after a compaction at ${at}; earlier turns are not recorded.`)
  }

  const withAgents = picked.has('agents')
  const withPlugins = picked.has('hooks')
  const tokens = tokensOf(all)
  let n = 0
  for (const turn of scope) {
    const ofTurn = shown.filter(r => r.turnId === turn.turnId)
    if (ofTurn.length === 0) continue
    lines.push('', `"${firstWords(turn.text)}"`, '')
    lines.push(withPlugins
      ? '| # | Kind | Name | Target | Plugins | Outcome | ms | Tokens |'
      : '| # | Kind | Name | Target | Outcome | ms | Tokens |')
    lines.push(withPlugins ? '| --- | --- | --- | --- | --- | --- | --- | --- |' : '| --- | --- | --- | --- | --- | --- | --- |')
    for (const { row, indent } of orderRows(ofTurn, withAgents)) {
      n += 1
      const plugins = withPlugins ? ` ${cell(row.plugins)} |` : ''
      lines.push(`| ${n} | ${row.kind} | ${cell(nameOf(row, all, withAgents, indent))} | ${cell(row.target)} |${plugins} ${row.outcome} | ${cell(row.ms)} | ${cell(tokens.get(row.id))} |`)
    }
    lines.push('', turnTotal(turn, all, now))
  }

  lines.push('')
  for (const c of selection.categories) {
    lines.push(`${c}: ${shown.filter(r => r.kind === c).length}`)
  }
  const toolRows = shown.filter(r => r.kind === 'tools')
  const files = new Set(toolRows.filter(r => FILE_TOOLS.has(r.name)).map(r => r.target.split(' ')[0]))
  lines.push(`Distinct files: ${files.size}`)
  const firstEdit = shown.findIndex(r => r.kind === 'tools' && EDIT_TOOLS.has(r.name))
  if (firstEdit >= 0) lines.push(`Rows before the first edit: ${firstEdit}`)
  if (scope.length > 1) lines.push(...tokenTotals(all))   // a single turn already has its total under the table
  const checks = toolRows.filter(r => r.name === 'Bash' && CHECK_RUNNERS.some(c => r.target.startsWith(c))).map(r => r.target)
  lines.push(checks.length > 0 ? `Checked: ${checks.join('; ')}` : 'Checked: nothing.')

  return lines.join('\n')
}

// The live pane: fixed-width columns so rows line up; Target takes the room
// the others leave. Kind, Name, Target, [Plugins,] Outcome, ms.
const PANE_HEADER = ['kind', 'name', 'target', 'plugins', 'outcome', 'tokens', 'ms']

function paneWidths(width: number, withPlugins: boolean): number[] {
  const widths = withPlugins ? [8, 20, 0, 14, 7, 7, 6] : [8, 20, 0, 7, 7, 6]   // 7 fits context, blocked, running
  const used = widths.reduce((a, b) => a + b, 0) + widths.length - 1
  widths[2] = Math.max(8, width - used)
  return widths
}

// Columns kept free at the pane's right edge, so right-aligned ms does not touch the border.
export const PANE_MARGIN = 2

// Each cell fitted to its column: cut with an ellipsis, padded; ms right-aligned.
function fitCells(cells: string[], paneWidth: number, withPlugins: boolean): string[] {
  const widths = paneWidths(Math.max(1, paneWidth - PANE_MARGIN), withPlugins)
  const last = cells.length - 1
  return cells.map((c, i) => {
    const w = widths[i] ?? 0
    return i === last ? trim(c, w).padStart(w) : trim(c, w).padEnd(w)
  })
}

function paneCells(cells: string[], paneWidth: number, withPlugins: boolean): string {
  return fitCells(cells, paneWidth, withPlugins).join(' ').slice(0, Math.max(1, paneWidth - PANE_MARGIN)).trimEnd()
}

export function paneHeader(width: number, withPlugins: boolean): string {
  return paneCells(withPlugins ? PANE_HEADER : PANE_HEADER.filter(h => h !== 'plugins'), width, withPlugins)
}

// The header's cells for the pane's sort buttons, fitted like the rows. A
// sorted column ends in its mark; where the label fills the column the mark
// takes its last place, so it is never cut off.
export function paneHeaderCells(width: number, withPlugins: boolean, marks: Partial<Record<string, string>> = {}): { column: string; text: string }[] {
  const labels = withPlugins ? PANE_HEADER : PANE_HEADER.filter(h => h !== 'plugins')
  const widths = paneWidths(Math.max(1, width - PANE_MARGIN), withPlugins)
  const marked = labels.map((label, i) => {
    const mark = marks[label] ?? ''
    const w = widths[i] ?? 0
    return mark === '' || label.length + mark.length <= w ? label + mark : label.slice(0, Math.max(0, w - mark.length)) + mark
  })
  const fitted = fitCells(marked, width, withPlugins)
  return labels.map((column, i) => ({ column, text: fitted[i] ?? '' }))
}

export function paneLine(row: Row, width: number, withPlugins: boolean, tokens = ''): string {
  const ms = row.ms === undefined ? '' : String(row.ms)
  const cells = withPlugins
    ? [row.kind, row.name, row.target, row.plugins ?? '', row.outcome, tokens, ms]
    : [row.kind, row.name, row.target, row.outcome, tokens, ms]
  return paneCells(cells, width, withPlugins)
}

// --- Pane colors. Kind and name share one blue, strongest for the kinds that
// usually cost the most tokens (model, then tools, context, hooks); everything
// else is a grey step, so only token weight and failures carry warning colors.
// Greys are hex, so there is one palette for dark themes and one for light.

export type Segment = { text: string; color?: string; bold?: boolean; underline?: boolean }

export type Palette = {
  kind: Record<Row['kind'], string>
  label: string; value: string; separator: string
  target: string; plugins: string; outcome: string; tokens: string
  ms: [string, string, string, string, string]   // under 10, 100, 1k, 10k, and above
}

// Hex colors: exact in a truecolor terminal. Where Claude Code falls back to
// 16 colors (no COLORTERM=truecolor) the blues collapse into white and cyan.
const ramp = (model: string, tools: string, context: string, hooks: string): Palette['kind'] =>
  ({ model, tools, mcp: tools, skills: tools, agents: tools, commands: tools, context, hooks })

export const DARK: Palette = {
  kind: ramp('#a3b2ff', '#8391d6', '#6872a6', '#5a628e'),
  label: '#8a8a8a', value: '#b2b2b2', separator: '#585858',
  target: '#767676', plugins: '#626262', outcome: '#6c6c6c', tokens: '#b2b2b2',
  ms: ['#4e4e4e', '#626262', '#767676', '#949494', '#bcbcbc'],
}

export const LIGHT: Palette = {
  kind: ramp('#3a4fd6', '#5a68b8', '#7d86b8', '#a3a8c6'),
  label: '#767676', value: '#4e4e4e', separator: '#b2b2b2',
  target: '#767676', plugins: '#9e9e9e', outcome: '#8a8a8a', tokens: '#4e4e4e',
  ms: ['#c6c6c6', '#a8a8a8', '#8a8a8a', '#6c6c6c', '#4e4e4e'],
}

// The `theme` setting's value: `light`, `light-daltonized`, `light-ansi` are light.
export const paletteFor = (theme: unknown): Palette => (typeof theme === 'string' && theme.startsWith('light') ? LIGHT : DARK)

export function outcomeStyle(outcome: Row['outcome'], pal: Palette = DARK): Omit<Segment, 'text'> {
  if (outcome === 'error' || outcome === 'denied' || outcome === 'blocked') return { color: 'error', bold: true }
  if (outcome === 'running') return { color: 'warning' }
  return { color: pal.outcome }
}

// `~2.0k`, `640`, `48.3k` back to a number.
function tokenCount(text: string): number {
  const m = /^[~+]?([\d.]+)(k?)$/.exec(text.trim())
  return m ? Number(m[1]) * (m[2] === 'k' ? 1000 : 1) : 0
}

// Under 1k a quiet grey; from 1k warning, over 10k error. Model rows too:
// their number is what the request wrote.
export function tokenStyle(text: string, pal: Palette = DARK): Omit<Segment, 'text'> {
  const n = tokenCount(text)
  if (n > 10000) return { color: 'error', bold: true }
  if (n >= 1000) return { color: 'warning', bold: true }
  return { color: pal.tokens }
}

// One grey step per power of ten, stronger the longer it took.
export function msStyle(ms: number | undefined, pal: Palette = DARK): Omit<Segment, 'text'> {
  if (ms === undefined) return {}
  const step = ms < 10 ? 0 : ms < 100 ? 1 : ms < 1000 ? 2 : ms < 10000 ? 3 : 4
  return { color: pal.ms[step] }
}

export function paneSegments(row: Row, width: number, withPlugins: boolean, tokens = '', pal: Palette = DARK): Segment[] {
  const ms = row.ms === undefined ? '' : String(row.ms)
  const cells: [string, Omit<Segment, 'text'>][] = [
    [row.kind, { color: pal.kind[row.kind], bold: true }],
    [row.name, { color: pal.kind[row.kind] }],
    [row.target, { color: pal.target }],
    ...(withPlugins ? [[row.plugins ?? '', { color: pal.plugins }] as [string, Omit<Segment, 'text'>]] : []),
    [row.outcome, outcomeStyle(row.outcome, pal)],
    [tokens, tokenStyle(tokens, pal)],
    [ms, msStyle(row.ms, pal)],
  ]
  const fitted = fitCells(cells.map(c => c[0]), width, withPlugins)
  return fitted.flatMap((text, i) => [...(i > 0 ? [{ text: ' ' }] : []), { text, ...cells[i]?.[1] }])
}

// The pane's row as cells of their own, each with its column's width: a surface
// that draws proportional text (the desktop) lines the columns up by the cell
// boxes, never by padding. Text is cut to the column, never padded.
export type Cell = Segment & { width: number; isRight: boolean }

export function paneRowCells(row: Row, width: number, withPlugins: boolean, tokens = '', pal: Palette = DARK): Cell[] {
  const widths = paneWidths(Math.max(1, width - PANE_MARGIN), withPlugins)
  const segments = paneSegments(row, width, withPlugins, tokens, pal).filter((_, i) => i % 2 === 0)
  return segments.map((s, i) => ({ ...s, text: s.text.trim(), width: widths[i] ?? 0, isRight: i === segments.length - 1 }))
}

export function paneHeaderWidths(width: number, withPlugins: boolean): number[] {
  return paneWidths(Math.max(1, width - PANE_MARGIN), withPlugins)
}

// Words with a digit (and the arrow between two counts) are values, `·` a
// separator, the rest labels. Neighbours of one kind merge into one segment.
export function labelValueSegments(text: string, pal: Palette = DARK): Segment[] {
  const out: Segment[] = []
  for (const [i, word] of text.split(' ').entries()) {
    const color = word === '·' ? pal.separator : /\d|^→$/.test(word) ? pal.value : pal.label
    const prev = out.at(-1)
    if (prev !== undefined && prev.color === color) prev.text += ` ${word}`
    else out.push(...(i > 0 ? [{ text: ' ' }] : []), { text: word, color })
  }
  return out.filter(s => s.text !== '')
}

// The counters line above the table, in the footer's label and value colors.
export function counterSegments(counts: [string, number][], pal: Palette = DARK): Segment[] {
  return labelValueSegments(counts.map(([c, n]) => `${c} ${n}`).join(' · '), pal)
}

// Where the name column starts: the kind column and the space after it.
export const NAME_COLUMN = paneWidths(80, false)[0]! + 1

// One line of the pane's footer, fitted to the pane. Its figures start under
// the name column: the first line puts `Total:` in front of them, the others
// are indented to the same place.
// The cells the footer's figures have: the pane less its margin and the lead.
export const paneTotalRoom = (width: number) => Math.max(1, width - PANE_MARGIN - NAME_COLUMN)

// `isCut` false leaves the cutting to the surface: proportional text (the desktop)
// fits more characters than the room's cells, so a cut by count stops short.
export function paneTotalSegments(line: string, width: number, isFirst: boolean, pal: Palette = DARK, isCut = true): Segment[] {
  const room = isCut ? paneTotalRoom(width) : Infinity
  // `Total:` heads the first line, `Agents:` the subagents' block; the rest are indented.
  const head = isFirst && line.startsWith('Total:') ? 'Total:' : line.startsWith('subagents:') ? 'subagents:' : undefined
  const lead: Segment = head !== undefined
    ? { text: (head === 'Total:' ? 'Total:' : 'Agents:').padEnd(NAME_COLUMN), color: pal.value, bold: true }
    : { text: ' '.repeat(NAME_COLUMN) }
  const rest = head !== undefined ? line.slice(head.length).trim() : line
  return [lead, ...labelValueSegments(trim(rest, room), pal)]
}

